import path from 'node:path';
import { createTools } from './tools.js';
import { openClause } from './storage.js';
export const name = 'dsh-legal-clause';
export const inject = ['tools', 'storageDomain'];
export async function apply(ctx) { const baseDir = process.env.DSH_CLAUSE_HOME ?? path.join(process.env.DSH_HOME ?? process.cwd(), 'storages', 'dsh-legal-clause'); const { contracts, playbooks } = await openClause(ctx); for (const t of createTools({ contracts, playbooks, baseDir }))
    ctx.tools.register(t); }
